def is_unique(word:str) -> bool:
    letters = set(word)
    return len(letters) == len(word)


def search_for_substring(message: str, num: int) -> int:
    length = len(message)
    for i in range(length):
        word = message[i:i+num]
        if is_unique(word):
            print(message[:i+num])
            print(message[i:i+num])
            return i+num
    return length

